frappe.listview_settings["Patient"] = {
    formatters: {
        mobile(value) {
            if (!value) {
                return "";
            }

            const phone = String(value).replace(/\s+/g, "");

            // Don't mask very short numbers
            if (phone.length <= 4) {
                return phone;
            }

            const firstTwo = phone.slice(0, 2);
            const lastTwo = phone.slice(-2);
            const maskedCount = Math.max(phone.length - 4, 1);

            return `${firstTwo}${"*".repeat(maskedCount)}${lastTwo}`;
        }
    }
};
